-- 004: archive the first-pass import and re-import David's RLX list, keeping every row. Applied Oct 16, 2026.
-- The hard wipe was declined, so the 635 old rows stay in the Archive. Duplicates are flagged in Review, never merged.
select set_config('app.actor','a4643b4e-012b-4b1a-9aac-ac35002048b2',false), set_config('app.via','claude',false);
update public.companies set archived_at=now(), archived_by='a4643b4e-012b-4b1a-9aac-ac35002048b2', archive_status='archived', archive_reason='Replaced by clean re-import of David''s RLX list (Oct 16, 2026)' where archived_at is null;
insert into public.companies (name,specialty,address,city,state,zip,main_phone,fax,notes,lead_source_channel,org_types,stage)
select b.name,b.specialty,b.address,b.city,b.state,b.zip,b.main_phone,b.fax,b.notes,'RLX list import','{Clinic}','Lead'
from backup.companies_20261016 b where b.name <> 'Test clinic' and (b.name, coalesce(b.city,'')) not in (('Benton Medical','Benton'),('WK Louisiana Family Practice','Bossier City'),('Fleur de Lis Rural Health Clinic','Church Point'),('Pediatric Group of Acadiana - Church Point','Church Point'),('Cottonport Family Clinic','Cottonport'),('Ochsner Health Center - Eunice','Eunice'),('North Oaks Urological Associates','Hammond'),('North Oaks Wound Care Center','Hammond'),('Butler-Abshire Clinic','Haynesville'),('Claiborne Family Medical Clinic','Homer'),('Homer Medical Clinic','Homer'),('Family Medicine Clinic - Mansura','Mansura'),('Mansura Family Clinic','Mansura'),('Marksville Family Clinic','Marksville'),('Blanchard Medical','Shreveport'),('Simmesport Family Clinic','Simmesport'),('Southern ENT Associates - Morgan City','Morgan City')) order by b.name, b.city;
