insert into public.review_items (kind, entity, entity_id, related_id, reason)
select 'possible_duplicate','companies', b.id, a.id, 'Same phone and street number in the same city (merged together in the first import)'
from public.companies a join public.companies b on a.id < b.id and a.archived_at is null and b.archived_at is null
 and private.norm(a.city) = private.norm(b.city) and private.norm(a.main_phone) = private.norm(b.main_phone)
 and substring(a.address from '^\s*(\d+)') = substring(b.address from '^\s*(\d+)')
where a.name in ('Benton Medical','Blanchard Medical','Butler Abshire Medical Clinic','Butler-Abshire Clinic','Claiborne Family Medical Clinic','Cottonport Family Clinic','Family Medicine Clinic - Mansura','Fleur de Lis Rural Health Clinic','Fleur-De-Lis Rural Health Clinic','Homer Medical Clinic','Mansura Family Clinic','Marksville Family Clinic','North Oaks Urological Associates','North Oaks Wound Care Center','Ochsner Health Center - Eunice','Pediatric Group of Acadiana & Church Point Clinic','Pediatric Group of Acadiana - Church Point','Simmesport Family Clinic','Southern ENT Associates - Morgan City','WK Louisiana Family Practice') and b.name in ('Benton Medical','Blanchard Medical','Butler Abshire Medical Clinic','Butler-Abshire Clinic','Claiborne Family Medical Clinic','Cottonport Family Clinic','Family Medicine Clinic - Mansura','Fleur de Lis Rural Health Clinic','Fleur-De-Lis Rural Health Clinic','Homer Medical Clinic','Mansura Family Clinic','Marksville Family Clinic','North Oaks Urological Associates','North Oaks Wound Care Center','Ochsner Health Center - Eunice','Pediatric Group of Acadiana & Church Point Clinic','Pediatric Group of Acadiana - Church Point','Simmesport Family Clinic','Southern ENT Associates - Morgan City','WK Louisiana Family Practice')
 and not exists (select 1 from public.review_items ri where ri.kind='possible_duplicate' and ri.status='open'
   and ((ri.entity_id=a.id and ri.related_id=b.id) or (ri.entity_id=b.id and ri.related_id=a.id)));
select set_config('app.actor','',false), set_config('app.via','',false);
select (select count(*) from companies where archived_at is null) active, (select count(*) from companies where archived_at is not null) archived, (select count(*) from review_items where status='open') flags, (select count(*) from audit_log where via='claude') claude_log;